import { z } from "zod";
import { getRequestIdentity } from "@/lib/auth/identity";
import { cancelAccountDeletion, finalizeAccountDeletion, getLinkedStripeCustomer, getPhase6Status, markAccountSubscriptionsCanceled, prepareAccountDeletion } from "@/lib/billing/server";
import { getStripe } from "@/lib/billing/stripe";
import { ApiRequestError, apiError, apiOk, parseJson, requestContext } from "@/lib/server/api";
import { logEvent, requestSubjectKey } from "@/lib/server/observability";
import { createAdminClient } from "@/lib/supabase/admin";

export const runtime="nodejs";
const schema=z.object({confirmation:z.literal("DELETE")});
const REQUIRED_PHASE6_SCHEMA="20260902034500";
function isReady(value:unknown){return Boolean(value&&typeof value==="object"&&!Array.isArray(value)&&(value as Record<string,unknown>).ready===true&&(value as Record<string,unknown>).schemaVersion===REQUIRED_PHASE6_SCHEMA);}

async function cancelLinkedSubscriptions(userId:string){
  const customerId=await getLinkedStripeCustomer(userId);
  if(!customerId){await markAccountSubscriptionsCanceled(userId);return 0;}
  const stripe=getStripe();
  let startingAfter:string|undefined;
  let canceled=0;
  do{
    const page=await stripe.subscriptions.list({customer:customerId,status:"all",limit:100,...(startingAfter?{starting_after:startingAfter}:{})});
    for(const subscription of page.data){
      if(subscription.status==="canceled"||subscription.status==="incomplete_expired")continue;
      await stripe.subscriptions.cancel(subscription.id);
      canceled+=1;
    }
    if(!page.has_more)break;
    const last=page.data.at(-1)?.id;
    if(!last)throw new Error("subscription_pagination_failed");
    startingAfter=last;
  }while(startingAfter);
  await markAccountSubscriptionsCanceled(userId);
  return canceled;
}

export async function POST(request:Request){
  const context=requestContext(request,"/api/account/delete");
  let identity:Awaited<ReturnType<typeof getRequestIdentity>>|null=null;
  let prepared=false;
  try{
    const parsed=await parseJson(request,schema,2_048);
    if(parsed.confirmation!=="DELETE")return apiError(context,"confirmation_required","Type DELETE to confirm account deletion.",400);
    identity=await getRequestIdentity();
    if(!identity)return apiError(context,"auth_required","Sign in before deleting an account.",401);
    if(!isReady(await getPhase6Status()))return apiError(context,"deletion_unavailable","Account deletion is not ready until the final billing migration is verified.",503);
    const userIdHash=requestSubjectKey(request,identity.userId);
    await prepareAccountDeletion(identity.userId);prepared=true;
    const canceledSubscriptions=await cancelLinkedSubscriptions(identity.userId);
    const admin=createAdminClient();
    const {error}=await admin.auth.admin.deleteUser(identity.userId);
    if(error){
      try{await cancelAccountDeletion(identity.userId);prepared=false;}catch{/* outer catch retries; cron clears a stale marker if both attempts fail */}
      throw error;
    }
    let reconciliationPending=false;
    try{await finalizeAccountDeletion(identity.userId);prepared=false;}catch{reconciliationPending=true;prepared=false;}
    logEvent("account_deleted",{requestId:context.requestId,userIdHash,reconciliationPending,canceledSubscriptions});
    return apiOk(context,{deleted:true,reconciliationPending,canceledSubscriptions});
  }catch(error){
    if(error instanceof ApiRequestError)return apiError(context,error.code,error.message,error.status);
    if(prepared&&identity){try{await cancelAccountDeletion(identity.userId);prepared=false;}catch{/* cron safely cancels stale pending deletion when the Auth identity still exists */}}
    logEvent("account_delete_failed",{requestId:context.requestId,subjectHash:requestSubjectKey(request)});
    return apiError(context,"account_delete_failed","Account deletion could not be completed. Any linked recurring billing must be canceled before the identity can be removed.",503);
  }
}

let lastEdit = null;

function inputSelection() {
  const target = document.activeElement;
  if (!(target instanceof HTMLTextAreaElement || target instanceof HTMLInputElement)) return null;
  const start = target.selectionStart ?? 0;
  const end = target.selectionEnd ?? start;
  if (end <= start) return null;
  return { kind: "input", target, start, end, text: target.value.slice(start, end) };
}

function richSelection() {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0 || selection.isCollapsed) return null;
  const range = selection.getRangeAt(0);
  const host = range.commonAncestorContainer.nodeType === Node.ELEMENT_NODE
    ? range.commonAncestorContainer
    : range.commonAncestorContainer.parentElement;
  const editable = host?.closest?.('[contenteditable="true"]');
  return { kind: editable ? "contenteditable" : "readonly", range: range.cloneRange(), text: selection.toString(), editable };
}

function currentSelection() {
  return inputSelection() || richSelection();
}

function replaceSelection(replacement) {
  const selection = currentSelection();
  if (!selection || !selection.text) return { ok: false, reason: "Select text in an editable field first." };

  if (selection.kind === "input") {
    const { target, start, end } = selection;
    lastEdit = { kind: "input", target, start, replacementLength: replacement.length, original: selection.text };
    target.setRangeText(replacement, start, end, "end");
    target.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertReplacementText", data: replacement }));
    return { ok: true };
  }

  if (selection.kind === "contenteditable" && selection.editable) {
    const htmlBefore = selection.editable.innerHTML;
    const range = selection.range;
    range.deleteContents();
    range.insertNode(document.createTextNode(replacement));
    selection.editable.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "insertReplacementText", data: replacement }));
    lastEdit = { kind: "contenteditable", target: selection.editable, htmlBefore };
    return { ok: true };
  }

  return { ok: false, reason: "The selected text is read-only. Use Copy result instead." };
}

function undoLast() {
  if (!lastEdit) return { ok: false, reason: "There is no in-page edit to undo." };

  if (lastEdit.kind === "input" && document.contains(lastEdit.target)) {
    const end = lastEdit.start + lastEdit.replacementLength;
    lastEdit.target.setRangeText(lastEdit.original, lastEdit.start, end, "end");
    lastEdit.target.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "historyUndo" }));
    lastEdit = null;
    return { ok: true };
  }

  if (lastEdit.kind === "contenteditable" && document.contains(lastEdit.target)) {
    lastEdit.target.innerHTML = lastEdit.htmlBefore;
    lastEdit.target.dispatchEvent(new InputEvent("input", { bubbles: true, inputType: "historyUndo" }));
    lastEdit = null;
    return { ok: true };
  }

  lastEdit = null;
  return { ok: false, reason: "The edited element is no longer available." };
}

chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
  if (message?.type === "selection") {
    const selection = currentSelection();
    sendResponse(selection ? { ok: true, text: selection.text, editable: selection.kind !== "readonly" } : { ok: false, reason: "Select some text first." });
    return;
  }
  if (message?.type === "replace") {
    sendResponse(replaceSelection(String(message.text || "")));
    return;
  }
  if (message?.type === "undo") {
    sendResponse(undoLast());
  }
});

